int QueryExceptionPayOrdersRespBody::parse_bytes(const byte* src, uint32 len)
{
	if (src == NULL) return -1;
	if (len < sizeof(uint32)) return -1;
	uint32 msglen = *(const uint32*)src;
	if (msglen < sizeof(uint32) || msglen > len) return -1;
	Aone2Decoder decoder(src + sizeof(uint32), msglen - sizeof(uint32));

	// m_pay_orders
	if (decoder.remain() == 0) return msglen;
	uint32 pay_orders_count = 0;
	if (!decoder.get_uint32(pay_orders_count)) return -1;
	for(uint32 i = 0; i < pay_orders_count; i++)
	{
		m_pay_orders.emplace_back(ExceptionPayOrder());
		ExceptionPayOrder& pay_orders_ = m_pay_orders.back();
		int pay_orders_ret = pay_orders_.parse_bytes(decoder.position(), decoder.remain());
		if (pay_orders_ret <= 0) return pay_orders_ret;
		if (!decoder.set_pos(decoder.position() + pay_orders_ret)) return -1;
	}

	return msglen;
}

int QueryExceptionPayOrdersRespBody::to_bytes(byte* dst, uint32 maxlen)
{
	if (dst == NULL) return -1;
	if (maxlen < sizeof(uint32)) return -1;
	Aone2Coder coder(dst + sizeof(uint32), maxlen - sizeof(uint32));

	// m_pay_orders
	if (!coder.set_uint32(m_pay_orders.size())) return -1;
	for(uint32 i = 0; i < (uint32)m_pay_orders.size(); i++)
	{
		int pay_orders_ret = m_pay_orders[i].to_bytes(coder.position(), coder.remain());
		if (pay_orders_ret <= 0) return pay_orders_ret;
		coder.set_pos(coder.position() + pay_orders_ret);
	}

	*(uint32*)dst = (coder.position() - dst);
	return *(uint32*)dst;
}

uint32 QueryExceptionPayOrdersRespBody::calc_length()
{
	uint32 length = 0;

	// m_pay_orders
	length += sizeof(uint32);
	for(uint32 i = 0; i < m_pay_orders.size(); i++)
	{
		length += m_pay_orders[i].calc_length();
	}

	return length + sizeof(uint32);
}

